import {profile,skills,interests,projects,constellation} from './data.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const head=(n,label,title,description='')=>`<div class="section-heading reveal"><p class="section-label"><span>${n}</span> ${label}</p><h2>${title}</h2>${description?`<p class="section-intro">${description}</p>`:''}</div>`;
const tags=items=>items.map(x=>`<span class="tag">${esc(x)}</span>`).join('');
const unavailable=label=>`<button type="button" disabled title="Not yet provided">${label}<span>Not added yet</span></button>`;
const social=(label,url)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:unavailable(label);
$('#sections').innerHTML=`
<section id="about" class="section about">${head('01','THE PERSON BEHIND THE CODE','Curiosity is my<br><em>starting point.</em>')}
<div class="about-grid"><div class="portrait-frame tilt reveal"><div class="portrait-grid"></div>${profile.portrait?`<img src="${esc(profile.portrait)}" alt="${esc(profile.name)}" loading="lazy">`:'<span class="portrait-monogram" aria-hidden="true">sr.</span><span class="portrait-note">PORTRAIT TO COME</span>'}<span class="frame-corner">⌜</span><div class="portrait-caption"><span>${profile.firstName}</span><small>LEARNING. BUILDING. EXPLORING.</small></div></div>
<div class="about-copy"><article class="reveal"><span class="micro">WHO I AM</span><h3>A computer scientist in the making.</h3><p>I’m ${profile.name}, a ${profile.degree} undergraduate at the ${profile.university}, ${profile.country}. My interests connect software, web technologies, artificial intelligence, data science, and databases.</p></article><article class="reveal"><span class="micro">WHAT DRIVES ME</span><p>I enjoy solving programming and algorithmic problems, learning new technologies, and turning theory into practical applications. Academic work, self-learning, and experimentation keep me moving forward.</p></article><div class="snapshot reveal"><div><span class="micro">BASED IN</span><strong>${profile.country}</strong></div><div><span class="micro">CURRENT FOCUS</span><strong>Software · AI · Data · Web</strong></div></div><div class="social-row">${social('GitHub',profile.github)}${social('LinkedIn',profile.linkedin)}${profile.resume?`<a href="${esc(profile.resume)}" download>Download CV ↓</a>`:unavailable('Download CV')}</div></div></div></section>
<section id="expertise" class="section expertise">${head('02','AREAS OF INTEREST','Many disciplines.<br><em>One curious mind.</em>','Technologies and ideas shaping my Computer Science journey.')}<div class="interest-grid">${interests.map(([title,description,icon],i)=>`<article class="interest-card spotlight reveal"><div class="interest-top"><span class="interest-icon" aria-hidden="true">${esc(icon)}</span><span class="micro">0${i+1}</span></div><h3>${title}</h3><p>${description}</p></article>`).join('')}</div></section>
<section id="skills" class="section skills">${head('03','TECHNICAL ECOSYSTEM','Everything is<br><em>connected.</em>','A growing foundation in programming, intelligent systems, and the technologies between them.')}<div class="ecosystem reveal"><div class="constellation"><svg viewBox="0 0 600 360" preserveAspectRatio="none" aria-hidden="true">${constellation.map((n,i)=>`<line data-edge="${i}" class="${i===0?'selected':''}" x1="300" y1="180" x2="${n.x*6}" y2="${n.y*3.6}"/>`).join('')}</svg><div class="constellation-core" aria-hidden="true">CS<span>EXPLORE</span></div>${constellation.map((n,i)=>`<button class="skill-node ${i===0?'selected':''}" data-node="${i}" aria-pressed="${i===0}" style="left:${n.x}%;top:${n.y}%">${n.name}</button>`).join('')}</div><div class="connection-detail"><span class="micro">SELECT A NODE TO EXPLORE</span><h3 id="connection-title">Python</h3><div id="connection-tags" class="tags">${tags(constellation[0].related)}</div><p>Connected concepts in my learning ecosystem.</p></div></div><div class="skill-lists">${Object.entries(skills).map(([group,items],i)=>`<details class="skill-group reveal" ${i===0?'open':''}><summary><span class="micro">0${i+1}</span>${group}<span class="expand">+</span></summary><div class="tags">${tags(items)}</div></details>`).join('')}</div><div class="pipeline reveal"><span class="micro">EXPLORING HOW MACHINES LEARN</span><div><span>Input data</span><i>→</i><span>Preprocessing</span><i>→</i><span>Neural representation</span><i>→</i><span>Output & evaluation</span></div><p>Machine learning · Deep learning · CNNs · Computer vision</p></div></section>
<section id="projects" class="section projects">${head('04','PROJECTS & PRACTICAL WORK','From understanding<br><em>to making.</em>','Applying Computer Science concepts through practical development and experimentation.')}<div class="project-toolbar"><div class="filters" role="group" aria-label="Filter project areas">${['All','Web','AI / ML','Database','Academic'].map((x,i)=>`<button data-filter="${x}" aria-pressed="${i===0}" class="${i===0?'active':''}">${x}</button>`).join('')}</div><span class="micro">A COLLECTION IN PROGRESS</span></div><div id="project-grid" class="project-grid" aria-live="polite"></div><p class="project-note">These are areas of practical work. Individual project titles, case studies, and links will be added as they become available.</p></section>
<section id="journey" class="section journey">${head('05','LEARNING BEYOND THE CLASSROOM','Better problems.<br><em>Stronger thinking.</em>')}<article id="achievements" class="competition reveal"><div><span class="pill">COMPETITIVE PROGRAMMING</span><h3>IEEEXtreme <em>19.0</em></h3><p>I participated in IEEEXtreme 19.0 as a member of Team <strong>DigitalVanguard</strong>, representing the University of Vavuniya, Sri Lanka.</p><p>An opportunity to apply programming, algorithmic thinking, logical reasoning, teamwork, and problem-solving in a competitive environment.</p><div class="tags">${tags(['Programming','Algorithms','Problem solving','Teamwork'])}</div></div><div class="algorithm"><div class="algorithm-label"><span class="micro">TRAVERSING POSSIBILITIES</span><span class="micro">01 → 07</span></div><svg viewBox="0 0 400 300" role="img" aria-label="Decorative animated binary tree traversal"><g class="tree-lines"><path d="M200 40L105 125L55 235M105 125L155 235M200 40L295 125L245 235M295 125L345 235"/></g>${[[200,40],[105,125],[55,235],[155,235],[295,125],[245,235],[345,235]].map(([x,y],i)=>`<g class="tree-node" style="--delay:${i*.8}s"><circle cx="${x}" cy="${y}" r="19"/><text x="${x}" y="${y+4}" text-anchor="middle">0${i+1}</text></g>`).join('')}</svg><span class="micro">AN ILLUSTRATION OF ALGORITHMIC THINKING</span></div></article>
<div class="journey-grid"><article id="education" class="education reveal"><span class="micro">ACADEMIC FOUNDATION</span><h3>Education</h3><div class="timeline-entry"><span class="status-dot"></span><span class="pill">${profile.status}</span><h4>${profile.degree}</h4><p>${profile.university}<br>${profile.country}</p></div></article><article class="community reveal"><span class="micro">GROWING TOGETHER</span><h3>Community & memberships</h3><div class="membership"><span class="membership-icon">◇</span><div><h4>IEEE</h4><p>Member</p></div></div><div class="membership"><span class="membership-icon">✳</span><div><h4>Zero Plastic Vavuniya Community</h4><p>Member</p></div></div></article></div>
<div class="parallel reveal"><div><span class="micro">COMPUTER SCIENCE FOUNDATION</span><h3>Different threads. Shared progress.</h3><p>Exploring parallel computing, MPI, and OpenMP.</p></div><div class="cores" aria-label="Decorative illustration of concurrent computing">${[1,2,3,4].map(i=>`<div class="compute-core" style="--delay:${i*.6}s"><span>CORE 0${i}</span><i></i><i></i><i></i></div>`).join('')}</div></div></section>
<section class="section principles">${head('06','HOW I APPROACH TECHNOLOGY','A little persistence.<br><em>A lot of possibility.</em>')}<div class="principle-list">${[['Problem solving','Approaching technical challenges through structured reasoning.'],['Continuous learning','Building knowledge through practice, experimentation, and self-learning.'],['Analytical thinking','Breaking complex problems into understandable components.'],['Technical curiosity','Exploring emerging technologies and new computing concepts.'],['Teamwork','Learning and solving problems collaboratively.']].map(([title,description],i)=>`<article class="reveal"><span class="micro">0${i+1}</span><h3>${title}</h3><p>${description}</p><span class="principle-star" aria-hidden="true">✳</span></article>`).join('')}</div><div class="exploration-stream" aria-label="Professional interests"><div>${[1,2].map(()=>'<span>Full-stack development</span><i>✳</i><span>Machine learning</span><i>✳</i><span>Data analytics</span><i>✳</i><span>Computer vision</span><i>✳</i>').join('')}</div></div></section>
<section class="section terminal-section">${head('07','A DIFFERENT WAY TO SAY HELLO','Meet me at<br><em>the command line.</em>','A small, simulated terminal. Curiosity encouraged.')}<div class="terminal reveal"><div class="terminal-bar"><span class="window-dots" aria-hidden="true">● ● ●</span><span>shaathveegaa — portfolio</span><span>⌘</span></div><div id="terminal-output" role="log" aria-label="Terminal output" aria-live="polite"><p><span class="terminal-accent">Welcome to my little corner of computing.</span><br>Type <strong>help</strong> to explore. This terminal only runs predefined portfolio commands.</p></div><form id="terminal-form" autocomplete="off"><label for="terminal-input">shaathveegaa<span>@portfolio</span>:~$</label><input id="terminal-input" aria-label="Terminal command" placeholder="help" spellcheck="false" maxlength="100"><button type="submit" aria-label="Run command">↵</button></form></div><div class="command-shortcuts"><span>TRY A COMMAND</span>${['whoami','skills','education','ieeextreme','future'].map(c=>`<button data-command="${c}">${c} ↵</button>`).join('')}</div></section>
<section class="section future"><div class="horizon" aria-hidden="true"></div><div class="reveal"><p class="section-label">08 &nbsp; THE JOURNEY AHEAD</p><h2>Still learning.<br>Still building.<br><em>Just getting started.</em></h2><p>My goal is to build a strong, adaptable career in Computer Science. To turn technical knowledge and curiosity into meaningful software and intelligent computing solutions — and keep exploring what comes next.</p><a class="text-link" href="#contact">Let’s be part of what comes next ↗</a></div></section>
<section id="contact" class="section contact">${head('09','LET’S MAKE A CONNECTION','Good things begin<br><em>with a conversation.</em>','Interested in technology, learning, collaboration, and opportunities to build meaningful digital solutions.')}<div class="contact-grid"><div class="contact-links">${social('Email',profile.email?'mailto:'+profile.email:'')}${social('LinkedIn',profile.linkedin)}${social('GitHub',profile.github)}<p>Personal contact links will appear here once added.</p></div><form id="contact-form"><div class="form-row"><label>Your name<input name="name" required maxlength="100" autocomplete="name" placeholder="Alex Morgan"></label><label>Email address<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="alex@example.com"></label></div><label>Subject<input name="subject" required maxlength="180" placeholder="What’s on your mind?"></label><label>Your message<textarea name="message" rows="4" required maxlength="5000" placeholder="Tell me a little about your idea..."></textarea></label><div class="form-bottom"><button class="button primary" type="submit">${profile.contactEndpoint?'Send message':'Check message'} <span>↗</span></button><small>${profile.contactEndpoint?'Let’s start a conversation.':'Sending is not connected yet. Your message stays in this browser.'}</small></div><p id="form-status" role="status"></p></form></div></section>
<div class="closing-type" aria-hidden="true">IDEAS. CODE. <em>POSSIBILITY.</em><span>BUILDING MY JOURNEY, ONE SOLUTION AT A TIME.</span></div>
<dialog id="project-dialog"><button class="dialog-close" aria-label="Close project details">×</button><div id="project-detail"></div></dialog>`;
function renderProjects(category='All'){$('#project-grid').innerHTML=projects.filter(p=>category==='All'||p.category===category).map(p=>`<article class="project-card spotlight"><div class="project-visual art-${p.id}" aria-hidden="true"><div class="project-art">${p.id==='web'?'&lt; / &gt;':p.id==='ai'?'✳':p.id==='database'?'▤':'{ }'}</div><span class="project-index">EXPLORATION / 0${projects.indexOf(p)+1}</span><span class="project-status">${p.status}</span></div><div class="project-copy"><span class="micro">${p.category}</span><h3>${p.title}</h3><p>${p.summary}</p><button class="text-link" data-project="${p.id}">Explore this area <span>↗</span></button></div></article>`).join('');}renderProjects();
$('.menu-toggle').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
const closeMenu=()=>{$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');};$$('nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('nav').classList.contains('open')){closeMenu();$('.menu-toggle').focus();}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;
function setMotion(value){motion=value;document.body.classList.toggle('motion-off',!value);$('#motion-toggle').setAttribute('aria-pressed',String(!value));$('#motion-toggle').textContent=value?'◌ Motion on':'◌ Motion off';document.documentElement.style.scrollBehavior=value?'smooth':'auto';document.dispatchEvent(new CustomEvent('portfolio:motion',{detail:value}));}
setMotion(motion);$('#motion-toggle').addEventListener('click',()=>setMotion(!motion));reduced.addEventListener('change',e=>setMotion(!e.matches));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>revealObserver.observe(el));
const activeObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}),{rootMargin:'-15% 0px -65% 0px'});$$('section[id]').forEach(s=>activeObserver.observe(s));
let scrollPending=false;const updateScroll=()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(max?scrollY/max*100:0)+'%';$('header').classList.toggle('scrolled',scrollY>30);scrollPending=false;};addEventListener('scroll',()=>{if(!scrollPending){requestAnimationFrame(updateScroll);scrollPending=true;}},{passive:true});updateScroll();
const descriptors=['intelligent systems','software development','data science','web technologies','computer vision','database systems'];let descriptorIndex=0;setInterval(()=>{if(!motion||document.hidden||scrollY>innerHeight)return;const el=$('#descriptor');el.style.opacity=0;el.style.transform='translateY(7px)';setTimeout(()=>{el.textContent=descriptors[++descriptorIndex%descriptors.length];el.style.opacity=1;el.style.transform='translateY(0)';},300);},3600);
if(matchMedia('(pointer: fine)').matches){document.addEventListener('pointermove',e=>{const cursor=$('.cursor');cursor.style.opacity=motion?'1':'0';cursor.style.transform=`translate(${e.clientX-13}px,${e.clientY-13}px)`;const card=e.target.closest('.spotlight,.tilt');if(card&&motion){const r=card.getBoundingClientRect();card.style.setProperty('--mx',`${e.clientX-r.left}px`);card.style.setProperty('--my',`${e.clientY-r.top}px`);if(card.classList.contains('tilt'))card.style.transform=`perspective(900px) rotateY(${(e.clientX-r.left-r.width/2)/45}deg) rotateX(${-(e.clientY-r.top-r.height/2)/55}deg)`;}});document.addEventListener('pointerout',e=>{const card=e.target.closest('.tilt');if(card&&!card.contains(e.relatedTarget))card.style.transform='';});document.addEventListener('pointerleave',()=>$('.cursor').style.opacity=0);$$('.magnetic').forEach(el=>{el.addEventListener('pointermove',e=>{if(!motion)return;const r=el.getBoundingClientRect();el.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.09}px,${(e.clientY-r.top-r.height/2)*.12}px)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});}
$$('[data-node]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.node),node=constellation[index];$$('[data-node]').forEach(el=>{el.classList.toggle('selected',el===button);el.setAttribute('aria-pressed',String(el===button));});$$('[data-edge]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.edge)===index));$('#connection-title').textContent=node.name;$('#connection-tags').innerHTML=tags(node.related);}));
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{$$('[data-filter]').forEach(el=>{el.classList.toggle('active',el===button);el.setAttribute('aria-pressed',String(el===button));});renderProjects(button.dataset.filter);}));
const dialog=$('#project-dialog');let projectTrigger;$('#project-grid').addEventListener('click',e=>{const button=e.target.closest('[data-project]');if(!button)return;projectTrigger=button;const p=projects.find(p=>p.id===button.dataset.project);$('#project-detail').innerHTML=`<span class="micro">${p.category} · ${p.status}</span><h2>${p.title}</h2><p>${p.summary}</p>${['Overview','Problem','Solution','Technologies','My contribution','Challenges','Key learning','Screenshots'].map((title,i)=>`<div class="case-row"><span class="micro">0${i+1}</span><h3>${title}</h3><p>${i===0?p.description:'Details have not been supplied yet.'}</p></div>`).join('')}<div class="social-row">${social('GitHub',p.github)}${social('Live demo',p.liveDemo)}</div>`;dialog.showModal();});$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>projectTrigger?.focus());
const history=[];let historyIndex=0;const responses={help:'Commands: whoami, about, skills, education, projects, ieeextreme, competition, interests, contact, future, clear',whoami:`${profile.name}\n${profile.degree} ${profile.status}\n${profile.university}, ${profile.country}`,about:'I learn, experiment, and solve problems through software, data, artificial intelligence, and emerging technologies.',skills:Object.entries(skills).map(([group,items])=>`${group}: ${items.join(', ')}`).join('\n\n'),education:`${profile.degree}\n${profile.university}, ${profile.country}\nStatus: ${profile.status}`,projects:'Areas of practical work: web development, databases, AI / ML, OOP, networking, MATLAB, parallel programming, and UI/UX. Individual project details are coming soon.',ieeextreme:'IEEEXtreme 19.0\nTeam DigitalVanguard\nUniversity of Vavuniya, Sri Lanka\nParticipant / Team Member',interests:interests.map(x=>x[0]).join(' · '),contact:profile.email||'Contact details have not been added yet.',future:'Still learning. Still building. Still exploring.'};responses.competition=responses.ieeextreme;
function runCommand(raw){const command=raw.trim().toLowerCase();if(!command)return;history.push(raw);historyIndex=history.length;const output=$('#terminal-output');if(command==='clear'){output.replaceChildren();return;}const line=document.createElement('p'),prompt=document.createElement('span'),answer=document.createElement('span');prompt.className='terminal-accent';prompt.textContent='❯ '+raw;answer.textContent=responses[command]||`Command not found: ${raw}. Type help to see available commands.`;line.append(prompt,document.createElement('br'),answer);output.append(line);while(output.children.length>30)output.firstElementChild.remove();output.scrollTop=output.scrollHeight;}
$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();runCommand($('#terminal-input').value);$('#terminal-input').value='';});$$('[data-command]').forEach(b=>b.addEventListener('click',()=>{runCommand(b.dataset.command);$('#terminal-input').focus({preventScroll:true});}));$('#terminal-input').addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.target.value=history[historyIndex]||'';}});
$('#contact-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,status=$('#form-status'),button=$('button[type=submit]',form);if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));if(Object.values(values).some(x=>!x.trim())){status.textContent='Please fill in each field with more than spaces.';return;}if(!profile.contactEndpoint){status.textContent='Your message is valid, but sending is not connected yet. Nothing has been sent or stored.';return;}button.disabled=true;button.textContent='Sending…';status.textContent='';try{const response=await fetch(profile.contactEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});if(!response.ok)throw Error('Send failed');status.textContent='Message sent. Thank you for reaching out!';form.reset();}catch{status.textContent='Your message could not be sent. Please try again later.';}finally{button.disabled=false;button.innerHTML='Send message <span>↗</span>';}});
import('./core.js').then(({createCore})=>createCore($('#core-scene'),()=>motion)).catch(()=>$('#core-scene').classList.add('fallback-only'));
console.info('Hello, developer 👋 Thanks for exploring Shaathveegaa’s portfolio.');
